function(t, c, api) {
  const p = api.ease(t / 4);
  const amp = api.lerp(0, 8, p);
  const freq = t * 3;
  const cx = api.w / 2;
  const cy = api.h / 2;

  c.strokeStyle = '#ffa500';
  c.lineWidth = 2;
  for (let i = 0; i < 3; i++) {
    const r = api.lerp(2, 40, p) + Math.sin(freq + i) * amp;
    c.beginPath();
    c.arc(cx, cy, r, 0, Math.PI * 2);
    c.stroke();
  }

  c.fillStyle = '#ffa500';
  c.beginPath();
  c.arc(cx, cy, 3 + Math.sin(freq) * 2, 0, Math.PI * 2);
  c.fill();

  if (t > 0.5) api.say("What is everything?", 1, 3);
}

function(t, c, api) {
  const zoom = api.lerp(1, 2.8, api.ease(t / 5));
  api.cam(0, 0, zoom, 0);

  const freq = t * 2;
  const pts = [];
  for (let i = 0; i < 40; i++) {
    const x = api.lerp(-35, 35, i / 40);
    const y = Math.sin(x * 0.12 + freq) * 14;
    pts.push([x, y]);
  }

  c.strokeStyle = '#00ffff';
  c.lineWidth = 3;
  api.path(pts, false);

  if (t > 1) api.say("A tiny string", 2, 4.5);

  api.cam(0, 0, 1, 0);
}

function(t, c, api) {
  const p = api.ease(t / 6);
  const mode = Math.floor(p * 3);
  const cx = api.w / 2;
  const cy = api.h / 2;

  const pts = [];
  for (let i = 0; i < 50; i++) {
    const x = api.lerp(-60, 60, i / 50);
    const waves = mode + 1;
    const y = Math.sin(x * 0.08 * waves + t * 2.5) * (18 - mode * 2);
    pts.push([x + cx, cy + y]);
  }

  c.strokeStyle = api.lerp('#00ffff', '#ffa500', p);
  c.lineWidth = 3;
  api.path(pts, false);

  if (t > 1.5) api.say("One string, many forms", 3, 5);
}

function(t, c, api) {
  const cx = api.w / 2;
  const cy = api.h / 2;
  const freq = t * 2;

  for (let s = 0; s < 5; s++) {
    const offset = (s - 2) * 35;
    const pts = [];
    for (let i = 0; i < 50; i++) {
      const x = api.lerp(-70, 70, i / 50);
      const wave = Math.sin(x * 0.08 + freq + s * 0.5) * 12;
      pts.push([cx + x, cy + offset + wave]);
    }

    const colors = ['#00ffff', '#ffa500', '#00ffff', '#ffa500', '#00ffff'];
    c.strokeStyle = colors[s];
    c.lineWidth = 2;
    api.path(pts, false);
  }

  if (t > 1.5) api.say("All the same thing", 2.5, 4.5);
}

function(t, c, api) {
  const cx = api.w / 2;
  const cy = api.h / 2;
  const freq = t * 2;

  for (let s = 0; s < 3; s++) {
    const baseY = cy + (s - 1) * 45;
    const interact = Math.sin(freq + s * 1.3) * 8;
    const pts = [];
    for (let i = 0; i < 40; i++) {
      const x = api.lerp(-65, 65, i / 40);
      const wave = Math.sin(x * 0.1 + freq + s) * 10 + interact;
      pts.push([cx + x, baseY + wave]);
    }
    c.strokeStyle = ['#00ffff', '#ffa500', '#00ffff'][s];
    c.lineWidth = 2;
    api.path(pts, false);
  }

  c.strokeStyle = 'rgba(255, 165, 0, 0.3)';
  c.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    const pulse = Math.sin(t * 3 + i) * 30;
    c.beginPath();
    c.arc(cx, cy, 30 + pulse, 0, Math.PI * 2);
    c.stroke();
  }

  if (t > 2) api.say("They all talk", 2.5, 5);
}

function(t, c, api) {
  const zoomFactor = api.lerp(2, 0.6, api.ease(t / 6));
  api.cam(0, 0, zoomFactor, 0);

  const cx = api.w / 2;
  const cy = api.h / 2;
  const freq = t * 2;

  const pts = [];
  for (let i = 0; i < 40; i++) {
    const x = api.lerp(-40, 40, i / 40);
    const y = Math.sin(x * 0.1 + freq) * 10;
    pts.push([x, y]);
  }
  c.strokeStyle = '#00ffff';
  c.lineWidth = 2;
  api.path(pts, false);

  if (api.seg(t, 3, 5) > 0) {
    c.fillStyle = '#ffa500';
    for (let i = 0; i < 12; i++) {
      const angle = (i / 12) * Math.PI * 2;
      const dist = api.lerp(20, 80, api.seg(t, 3, 5));
      const px = Math.cos(angle) * dist;
      const py = Math.sin(angle) * dist;
      c.beginPath();
      c.arc(px, py, 2, 0, Math.PI * 2);
      c.fill();
    }
  }

  api.cam(0, 0, 1, 0);
}

function(t, c, api) {
  const p = api.ease(t / 5);
  const cx = api.w / 2;
  const cy = api.h / 2;

  c.fillStyle = '#ffa500';
  for (let i = 0; i < 25; i++) {
    const angle = api.rand(i) * Math.PI * 2;
    const dist = api.lerp(40, 200, p);
    const x = cx + Math.cos(angle) * dist;
    const y = cy + Math.sin(angle) * dist;
    const size = api.lerp(1, 4, p) * (0.5 + api.rand(i + 10));
    c.beginPath();
    c.arc(x, y, size, 0, Math.PI * 2);
    c.fill();
  }

  const pts = [];
  for (let i = 0; i < 30; i++) {
    const x = api.lerp(-25, 25, i / 30);
    const y = Math.sin(x * 0.15 + t * 2) * 6;
    pts.push([x + cx, y + cy]);
  }
  c.strokeStyle = '#00ffff';
  c.lineWidth = 2;
  api.path(pts, false);

  if (t < 2.5) api.say("Everything vibrates", 0.5, 2);
}
